import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Клининговая компания: CRM заявок, сделок и выездов бригад"}>
      <p>{"У нас клининговая компания в Новосибирске: уборка квартир после ремонта, офисов и мойка окон. Два менеджера принимают заявки с сайта и по телефону, шесть бригад выезжают на объекты. Нужна CRM: карточка клиента (частное лицо или компания), заявка становится сделкой с этапами «новая», «расчёт», «согласована», «назначена бригада», «выполнена», «оплачена» или «отказ» с причиной. В сделке — адрес объекта, площадь, вид уборки, сумма, дата и время выезда, бригада. Бригадир видит только свои выезды на день и отмечает выполнение с фото результата. Менеджер видит свои сделки, руководитель — все, и раз в неделю хочет отчёт: выручка по видам уборки, загрузка бригад, причины отказов. На сайте — простая страница услуг с примерной ценой и формой заявки. Бухгалтерию ведёт клиент (клиент), отчёты ей нужны выгрузкой в таблицу. Подробное ТЗ прикладываю файлом."}</p>
      <ul>
        <li>{"Этапы сделки"}</li>
        <li>{"Причина отказа"}</li>
        <li>{"Назначение бригады"}</li>
        <li>{"Отметка выполнения с фото"}</li>
        <li>{"Недельный отчёт"}</li>
      </ul>
      <p>{"Менеджер видит только свои сделки"}</p>
      <p>{"Отказ требует причины"}</p>
      <p>{"Бригадир видит только свои выезды"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
